CREATE OR REPLACE FUNCTION public.hr_record_punch(_employee uuid, _kind text, _latitude numeric, _longitude numeric, _accuracy numeric) RETURNS public.hr_punches LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE e public.hr_employees; p public.hr_punches; lastp public.hr_punches; BEGIN SELECT * INTO e FROM public.hr_employees WHERE id = _employee AND active FOR UPDATE; IF e.id IS NULL OR auth.uid() IS NULL OR NOT(coalesce(e.auth_user_id = auth.uid(),false) OR public.hr_is_admin(e.account_id)) THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT * INTO lastp FROM public.hr_punches WHERE employee_id = e.id ORDER BY sequence DESC LIMIT 1; INSERT INTO public.hr_punches(account_id,employee_id,kind,latitude,longitude,accuracy,actor_id) VALUES(e.account_id,e.id,_kind,_latitude,_longitude,_accuracy,auth.uid()) RETURNING * INTO p; UPDATE public.hr_punches SET receipt_hash = encode(sha256(convert_to(p.id::text || p.recorded_at::text || coalesce(lastp.receipt_hash,''),'UTF8')),'hex') WHERE id = p.id RETURNING * INTO p; RETURN p; END $$;
COMMENT ON FUNCTION public.hr_record_punch(uuid,text,numeric,numeric,numeric) IS 'Never block original time punches because of schedule, interval, or sequence; report anomalies for review instead.';